<?php
declare(strict_types=1);
namespace Sentinel\Services;
use Sentinel\Core\{Database,RuntimeContext,HttpException};
final class RadioService
{
    use TenantOperations;
    public function __construct(private readonly Database $db,private readonly RuntimeContext $context,private readonly AuditService $audit,private readonly SiteAccessService $access) {}
    private function uuid(mixed $v):string {if(!is_string($v)||!preg_match('/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/Di',$v))throw HttpException::unprocessable('Use an operation UUID.');return strtolower($v);}
    private function channel(string $id,bool $member=true):array {$r=$this->row('radio_channels','channel_id',$id);$this->access->requireSite($r['site_id']);if(!(int)$r['active'])throw HttpException::conflict('Channel is disabled.');if($member&&!$this->db->fetch('SELECT member_id FROM radio_members WHERE company_id=:company AND channel_id=:channel AND user_id=:actor',['company'=>$this->company(),'channel'=>$id,'actor'=>$this->actor()]))throw HttpException::notFound('Your radio channel was not found.');return $r;}
    public function channels(bool $manage=false):array {$rows=$this->db->fetchAll('SELECT channel_id,site_id,channel_name,history_enabled,active,revision,floor_user_id,floor_until,floor_priority FROM radio_channels WHERE company_id=:company'.($manage?'':' AND EXISTS(SELECT 1 FROM radio_members m WHERE m.company_id=radio_channels.company_id AND m.channel_id=radio_channels.channel_id AND m.user_id=:actor)').' ORDER BY channel_id DESC LIMIT 200',$manage?['company'=>$this->company()]:['company'=>$this->company(),'actor'=>$this->actor()]);$out=[];foreach($rows as$r){if(!$this->access->allowed($r['site_id']))continue;if($manage)$r['members']=$this->db->fetchAll('SELECT user_id,joined_at FROM radio_members WHERE company_id=:company AND channel_id=:channel',['company'=>$this->company(),'channel'=>$r['channel_id']]);$out[]=$r;}return $out;}
    public function create(array $input):array {return $this->atomic(function()use($input){$this->fields($input,['site_id','channel_name','history_enabled']);$site=$this->access->requireSite($input['site_id']??null);if(!is_bool($input['history_enabled']??null))throw HttpException::unprocessable('Choose a history setting.');$name=$this->text($input['channel_name']??null,100);if($this->db->fetch('SELECT channel_id FROM radio_channels WHERE company_id=:company AND site_id=:site AND channel_name=:name',['company'=>$this->company(),'site'=>$site['site_id'],'name'=>$name]))throw HttpException::conflict('Channel name already exists at this site.');$this->db->execute('INSERT INTO radio_channels(company_id,site_id,channel_name,history_enabled,created_by_user_id) VALUES(:company,:site,:name,:history,:actor)',['company'=>$this->company(),'site'=>$site['site_id'],'name'=>$name,'history'=>(int)$input['history_enabled'],'actor'=>$this->actor()]);return $this->created('radio_channel');});}
    public function member(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['user_id','enabled']);$this->channel($id,false);$user=$this->row('users','user_id',$input['user_id']??null);if(!is_bool($input['enabled']??null)||$user['status']!=='ACTIVE')throw HttpException::unprocessable('Choose an active user and membership setting.');$keys=['company'=>$this->company(),'channel'=>$id,'user'=>$user['user_id']];$old=$this->db->fetch('SELECT member_id FROM radio_members WHERE company_id=:company AND channel_id=:channel AND user_id=:user',$keys);if($input['enabled']&&!$old)$this->db->execute('INSERT INTO radio_members(company_id,channel_id,user_id,joined_at,joined_after_message_id,joined_after_call_id) VALUES(:company,:channel,:user,:now,:after,:call_after)',$keys+['now'=>gmdate('Y-m-d H:i:s'),'after'=>(int)($this->db->fetch('SELECT MAX(message_id) AS n FROM radio_messages WHERE company_id=:company AND channel_id=:channel',['company'=>$this->company(),'channel'=>$id])['n']??0),'call_after'=>(int)($this->db->fetch('SELECT MAX(call_id) AS n FROM radio_priority_calls WHERE company_id=:company AND channel_id=:channel',['company'=>$this->company(),'channel'=>$id])['n']??0)]);elseif(!$input['enabled']){$this->db->execute('DELETE FROM radio_members WHERE company_id=:company AND channel_id=:channel AND user_id=:user',$keys);$this->db->execute('UPDATE radio_channels SET floor_hash=NULL,floor_until=NULL,floor_user_id=NULL WHERE company_id=:company AND channel_id=:channel AND floor_user_id=:user',$keys);}$this->audit->record('radio_member',$input['enabled']?'added':'removed',$id,[],[],['user_id'=>$user['user_id']]);return ['saved'=>true];});}
    public function disable(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['expected_revision']);$r=$this->channel($id,false);if($this->number($input['expected_revision']??null)!==(int)$r['revision'])throw HttpException::conflict('Channel changed.');$this->db->execute('UPDATE radio_channels SET active=0,revision=revision+1,floor_hash=NULL,floor_until=NULL,floor_user_id=NULL WHERE company_id=:company AND channel_id=:id',['company'=>$this->company(),'id'=>$id]);$this->audit->record('radio_channel','disabled',$id);return ['disabled'=>true];});}
    public function claim(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['operation_uuid','priority']);$c=$this->channel($id);$uuid=$this->uuid($input['operation_uuid']??null);if(!is_bool($input['priority']??null))throw HttpException::unprocessable('Choose a priority setting.');$priority=(int)$input['priority'];$now=gmdate('Y-m-d H:i:s');if($c['floor_until']!==null&&$c['floor_until']>$now&&(!$priority||(int)$c['floor_priority']===1))throw HttpException::conflict('Channel is busy. Release or wait for the current voice burst.');$lease=bin2hex(random_bytes(32));$until=gmdate('Y-m-d H:i:s',time()+30);$this->db->execute('UPDATE radio_channels SET floor_user_id=:actor,floor_hash=:hash,floor_until=:until,floor_priority=:priority,floor_uuid=:uuid WHERE company_id=:company AND channel_id=:id',['actor'=>$this->actor(),'hash'=>hash('sha256',$lease),'until'=>$until,'priority'=>$priority,'uuid'=>$uuid,'company'=>$this->company(),'id'=>$id]);
        if($priority&&!$this->db->fetch('SELECT call_id FROM radio_priority_calls WHERE company_id=:company AND caller_user_id=:actor AND operation_uuid=:uuid',['company'=>$this->company(),'actor'=>$this->actor(),'uuid'=>$uuid])){$this->db->execute('INSERT INTO radio_priority_calls(company_id,channel_id,caller_user_id,operation_uuid,created_at) VALUES(:company,:channel,:actor,:uuid,:now)',['company'=>$this->company(),'channel'=>$id,'actor'=>$this->actor(),'uuid'=>$uuid,'now'=>$now]);$call=(string)$this->db->connection()->lastInsertId();$this->audit->record('radio_priority_call','requested',$call);$p=new \Sentinel\Repositories\PermissionRepository($this->db,$this->context);foreach($this->db->fetchAll("SELECT m.user_id FROM radio_members m JOIN users u ON u.company_id=m.company_id AND u.user_id=m.user_id WHERE m.company_id=:company AND m.channel_id=:channel AND u.status='ACTIVE'",['company'=>$this->company(),'channel'=>$id])as$member){$u=(string)$member['user_id'];if($u===$this->actor()||!$p->userHasPermission($u,'radio.self'))continue;if($p->userHasPermission($u,'site_scope.restricted')&&!$this->db->fetch('SELECT grant_id FROM user_site_grants WHERE company_id=:company AND user_id=:user AND site_id=:site',['company'=>$this->company(),'user'=>$u,'site'=>$c['site_id']]))continue;$this->db->execute('INSERT INTO notifications(company_id,recipient_user_id,event_type,severity,title,message) VALUES(:company,:user,:type,:severity,:title,:message)',['company'=>$this->company(),'user'=>$u,'type'=>'RADIO_PRIORITY_REQUEST','severity'=>'CRITICAL','title'=>'Priority channel voice request','message'=>'Priority call #'.$call.' requested on '.$c['channel_name'].'. Open your channel and acknowledge receipt; use site response procedures.']);}}
        return ['lease'=>$lease,'expires_at'=>$until,'operation_uuid'=>$uuid,'max_recording_seconds'=>20,'note'=>'Audio is broadcast after release. Priority requests do not call external responders.'];});}
    public function release(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['lease']);$c=$this->channel($id);if((string)$c['floor_user_id']!==$this->actor()||!is_string($input['lease']??null)||!hash_equals((string)$c['floor_hash'],hash('sha256',$input['lease'])))throw HttpException::conflict('Your floor lease is no longer active.');$this->clearFloor($id);return ['released'=>true];});}
    private function clearFloor(string $id):void {$this->db->execute('UPDATE radio_channels SET floor_hash=NULL,floor_user_id=NULL,floor_until=NULL WHERE company_id=:company AND channel_id=:id',['company'=>$this->company(),'id'=>$id]);}
    public function send(string $id,array $input):array {return $this->atomic(function()use($id,$input){$this->fields($input,['lease','operation_uuid','mime_type','audio_base64']);$c=$this->channel($id);$uuid=$this->uuid($input['operation_uuid']??null);$encoded=$input['audio_base64']??null;$mime=$input['mime_type']??null;if(!is_string($encoded)||strlen($encoded)>700000||!in_array($mime,['audio/webm','audio/ogg','audio/mp4'],true))throw HttpException::unprocessable('Use a supported voice recording up to 512 KiB.');$bytes=base64_decode($encoded,true);if($bytes===false||strlen($bytes)<16||strlen($bytes)>524288||!(($mime==='audio/webm'&&str_starts_with($bytes,"\x1a\x45\xdf\xa3"))||($mime==='audio/ogg'&&str_starts_with($bytes,'OggS'))||($mime==='audio/mp4'&&substr($bytes,4,4)==='ftyp')))throw HttpException::unprocessable('The audio container is invalid.');$hash=hash('sha256',$id.'|'.$mime.'|'.$bytes);$old=$this->db->fetch('SELECT message_id,payload_hash FROM radio_messages WHERE company_id=:company AND sender_user_id=:actor AND operation_uuid=:uuid',['company'=>$this->company(),'actor'=>$this->actor(),'uuid'=>$uuid]);if($old){if(!hash_equals($old['payload_hash'],$hash))throw HttpException::conflict('Operation UUID already used for different audio.');return ['id'=>(string)$old['message_id'],'received'=>true];}
        if((string)$c['floor_user_id']!==$this->actor()||$c['floor_until']<gmdate('Y-m-d H:i:s')||$c['floor_uuid']!==$uuid||!is_string($input['lease']??null)||!hash_equals((string)$c['floor_hash'],hash('sha256',$input['lease'])))throw HttpException::conflict('Floor lease expired or was preempted. Request a new turn.');$this->db->execute('INSERT INTO radio_messages(company_id,channel_id,sender_user_id,operation_uuid,payload_hash,priority,mime_type,audio_base64,created_at,expires_at) VALUES(:company,:channel,:actor,:uuid,:hash,:priority,:mime,:audio,:now,:expiry)',['company'=>$this->company(),'channel'=>$id,'actor'=>$this->actor(),'uuid'=>$uuid,'hash'=>$hash,'priority'=>$c['floor_priority'],'mime'=>$mime,'audio'=>base64_encode($bytes),'now'=>gmdate('Y-m-d H:i:s'),'expiry'=>gmdate('Y-m-d H:i:s',time()+((int)$c['history_enabled']?30*86400:300))]);$result=$this->created('radio_message');$this->clearFloor($id);return $result+['received'=>true];});}
    public function feed(string $id,array $input):array {$this->fields($input,['after']);$c=$this->channel($id);$after=$this->number($input['after']??0,0);$member=$this->db->fetch('SELECT joined_at,joined_after_message_id,joined_after_call_id FROM radio_members WHERE company_id=:company AND channel_id=:channel AND user_id=:actor',['company'=>$this->company(),'channel'=>$id,'actor'=>$this->actor()]);$params=['company'=>$this->company(),'channel'=>$id,'after'=>max($after,(int)$member['joined_after_message_id']),'now'=>gmdate('Y-m-d H:i:s'),'joined'=>$member['joined_at']];$messages=$this->db->fetchAll('SELECT message_id,sender_user_id,priority,mime_type,created_at FROM radio_messages WHERE company_id=:company AND channel_id=:channel AND message_id>:after AND expires_at>:now AND created_at>=:joined ORDER BY message_id '.($after===0?'DESC':'ASC').' LIMIT 100',$params);if($after===0)$messages=array_reverse($messages);return ['floor_user_id'=>$c['floor_user_id'],'floor_until'=>$c['floor_until'],'messages'=>$messages,'priority_calls'=>$this->db->fetchAll('SELECT call_id,caller_user_id,created_at,acknowledged_at,acknowledged_by_user_id FROM radio_priority_calls WHERE company_id=:company AND channel_id=:channel AND call_id>:after_call AND created_at>=:joined AND created_at>=:since ORDER BY call_id DESC LIMIT 30',['company'=>$this->company(),'channel'=>$id,'joined'=>$member['joined_at'],'after_call'=>$member['joined_after_call_id'],'since'=>gmdate('Y-m-d H:i:s',time()-3600)])];}
    public function audio(string $id):array {$m=$this->row('radio_messages','message_id',$id);$this->channel((string)$m['channel_id']);$joined=$this->db->fetch('SELECT joined_at,joined_after_message_id,joined_after_call_id FROM radio_members WHERE company_id=:company AND channel_id=:channel AND user_id=:actor',['company'=>$this->company(),'channel'=>$m['channel_id'],'actor'=>$this->actor()]);if($m['message_id']<=$joined['joined_after_message_id']||$m['expires_at']<=gmdate('Y-m-d H:i:s')||$m['created_at']<$joined['joined_at']||$m['audio_base64']===null)throw HttpException::notFound('Audio expired or predates your membership.');$bytes=base64_decode($m['audio_base64'],true);if($bytes===false||!hash_equals($m['payload_hash'],hash('sha256',$m['channel_id'].'|'.$m['mime_type'].'|'.$bytes)))throw HttpException::conflict('Audio integrity check failed.');return ['bytes'=>$bytes,'mime'=>$m['mime_type']];}
    public function acknowledge(string $id):array {return $this->atomic(function()use($id){$call=$this->row('radio_priority_calls','call_id',$id);$this->channel((string)$call['channel_id']);$member=$this->db->fetch('SELECT joined_after_call_id FROM radio_members WHERE company_id=:company AND channel_id=:channel AND user_id=:actor',['company'=>$this->company(),'channel'=>$call['channel_id'],'actor'=>$this->actor()]);if((int)$call['call_id']<=(int)$member['joined_after_call_id']||$call['created_at']<gmdate('Y-m-d H:i:s',time()-3600))throw HttpException::notFound('The call predates your membership or is no longer current.');if((string)$call['caller_user_id']===$this->actor())throw HttpException::forbidden('A different channel member must acknowledge.');if($call['acknowledged_at']===null)$this->db->execute('UPDATE radio_priority_calls SET acknowledged_at=:now,acknowledged_by_user_id=:actor WHERE company_id=:company AND call_id=:id',['now'=>gmdate('Y-m-d H:i:s'),'actor'=>$this->actor(),'company'=>$this->company(),'id'=>$id]);$this->audit->record('radio_priority_call','acknowledged',$id);return ['acknowledged'=>true];});}
    public function purgeExpired():array {return $this->atomic(function(){$n=$this->db->execute('UPDATE radio_messages SET audio_base64=NULL WHERE company_id=:company AND expires_at<=:now AND audio_base64 IS NOT NULL',['company'=>$this->company(),'now'=>gmdate('Y-m-d H:i:s')]);return ['expired_audio_removed'=>$n];});}
}
